const body = $json.body || {};
const channelUrl = body.channelUrl || '';
const channelName = body.channelName || 'Canal Estratégico';

return [{
  json: {
    channelUrl,
    channelName,
    goldStandard: {
      viewsThreshold: '100k+',
      maxTopViews: 30,
      recentVideos: 10
    },
    vaultPath: '/sdcard/Documents/Obsidian VN/VN/04 - Estudos/' + channelName,
    dossierTemplate: '00 - Dossiê Mestre - ' + channelName + '.md',
    crossLinks: ['Bússola Inabalável', 'Livro da Vida', 'TCC']
  }
}];
